    col_borders = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    panel_h = row_borders[0] if row_borders else h
    panel_w = col_borders[0] if col_borders else w
    nr, nc = (h + 1) // (panel_h + 1), (w + 1) // (panel_w + 1)
    marks = {2: [], 3: []}
