def build(spansizes, marks, marker_loc=(0,0), trailing_border=False):
    n=len(spansizes); panel_total=sum(spansizes); size=panel_total+n-1+(1 if trailing_border else 0)
    g=[[0]*size for _ in range(size)]
    starts=[]; s=0
    for z in spansizes:
        starts.append(s); s+=z+1
    for k in range(n-1):
        br=starts[k]+spansizes[k]
        g[br]=[8]*size
        for r in range(size):g[r][br]=8
    if trailing_border:
        g[-1]=[8]*size
        for r in range(size):g[r][-1]=8
    for color,pts in marks.items():
        for pr,pc in pts:g[starts[pr]+marker_loc[0]][starts[pc]+marker_loc[1]]=color
    return g
